-- =============================================================================
-- Trackr@Uni-Ace - baseline schema
--
-- Conventions:
--   * All timestamps are stored as TIMESTAMPTZ (UTC on the wire). Business
--     hours are interpreted in the schedule's own timezone.
--   * Enum-like columns are plain VARCHAR guarded by CHECK constraints, so the
--     set of allowed values is enforced by the database as well as the
--     application (requirement 87).
--   * Primary keys are UUIDs generated by the application. Work events use a
--     client-generated UUID so that offline synchronisation is idempotent.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Login accounts. One row per human who can sign in (employee, supervisor,
-- administrator). Employee/supervisor profile data lives in its own table.
-- -----------------------------------------------------------------------------
CREATE TABLE user_accounts (
    id              UUID         PRIMARY KEY,
    email           VARCHAR(190) NOT NULL,
    password_hash   VARCHAR(120),
    role            VARCHAR(20)  NOT NULL,
    status          VARCHAR(30)  NOT NULL,
    display_name    VARCHAR(160) NOT NULL,
    last_login_at   TIMESTAMPTZ,
    failed_logins   INT          NOT NULL DEFAULT 0,
    locked_until    TIMESTAMPTZ,
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT uq_user_accounts_email UNIQUE (email),
    CONSTRAINT ck_user_accounts_role   CHECK (role IN ('EMPLOYEE', 'SUPERVISOR', 'ADMIN')),
    CONSTRAINT ck_user_accounts_status CHECK (status IN ('PENDING_ACTIVATION', 'ACTIVE', 'DISABLED'))
);

-- -----------------------------------------------------------------------------
-- Work schedules. Working days are stored as a comma separated list of
-- java.time.DayOfWeek names, e.g. 'MONDAY,TUESDAY,WEDNESDAY,THURSDAY,FRIDAY'.
-- -----------------------------------------------------------------------------
CREATE TABLE work_schedules (
    id                 UUID         PRIMARY KEY,
    name               VARCHAR(120) NOT NULL,
    start_time         TIME         NOT NULL,
    end_time           TIME         NOT NULL,
    working_days       VARCHAR(120) NOT NULL,
    break_start        TIME,
    break_end          TIME,
    break_paid         BOOLEAN      NOT NULL DEFAULT FALSE,
    timezone           VARCHAR(60)  NOT NULL DEFAULT 'Asia/Manila',
    active             BOOLEAN      NOT NULL DEFAULT TRUE,
    created_at         TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at         TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT uq_work_schedules_name UNIQUE (name),
    CONSTRAINT ck_work_schedules_break CHECK (
        (break_start IS NULL AND break_end IS NULL) OR
        (break_start IS NOT NULL AND break_end IS NOT NULL AND break_end > break_start)
    )
);

-- -----------------------------------------------------------------------------
-- Non-working dates. A holiday with a NULL branch applies company-wide.
-- -----------------------------------------------------------------------------
CREATE TABLE holidays (
    id          UUID         PRIMARY KEY,
    holiday_date DATE        NOT NULL,
    name        VARCHAR(160) NOT NULL,
    branch      VARCHAR(20),
    paid        BOOLEAN      NOT NULL DEFAULT TRUE,
    created_at  TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT uq_holidays_date_branch UNIQUE (holiday_date, branch),
    CONSTRAINT ck_holidays_branch CHECK (branch IS NULL OR branch IN ('MANILA', 'CEBU'))
);

-- -----------------------------------------------------------------------------
-- Offices, warehouses and other field locations, each with a geofence.
-- -----------------------------------------------------------------------------
CREATE TABLE locations (
    id               UUID          PRIMARY KEY,
    name             VARCHAR(160)  NOT NULL,
    type             VARCHAR(20)   NOT NULL,
    branch           VARCHAR(20),
    address          VARCHAR(400),
    latitude         DOUBLE PRECISION NOT NULL,
    longitude        DOUBLE PRECISION NOT NULL,
    geofence_radius_m INT          NOT NULL DEFAULT 100,
    active           BOOLEAN       NOT NULL DEFAULT TRUE,
    created_at       TIMESTAMPTZ   NOT NULL DEFAULT now(),
    updated_at       TIMESTAMPTZ   NOT NULL DEFAULT now(),
    CONSTRAINT uq_locations_name UNIQUE (name),
    CONSTRAINT ck_locations_type   CHECK (type IN ('OFFICE', 'WAREHOUSE', 'FIELD')),
    CONSTRAINT ck_locations_branch CHECK (branch IS NULL OR branch IN ('MANILA', 'CEBU')),
    CONSTRAINT ck_locations_lat    CHECK (latitude BETWEEN -90 AND 90),
    CONSTRAINT ck_locations_lon    CHECK (longitude BETWEEN -180 AND 180),
    CONSTRAINT ck_locations_radius CHECK (geofence_radius_m BETWEEN 10 AND 5000)
);

-- -----------------------------------------------------------------------------
-- Supervisors. Scope is expressed by the employees assigned to them, plus an
-- optional branch restriction used when listing unassigned data.
-- -----------------------------------------------------------------------------
CREATE TABLE supervisors (
    id             UUID         PRIMARY KEY,
    user_id        UUID         NOT NULL,
    first_name     VARCHAR(80)  NOT NULL,
    last_name      VARCHAR(80)  NOT NULL,
    email          VARCHAR(190) NOT NULL,
    contact_number VARCHAR(40),
    branch         VARCHAR(20)  NOT NULL,
    scope_note     VARCHAR(300),
    active         BOOLEAN      NOT NULL DEFAULT TRUE,
    created_at     TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at     TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT fk_supervisors_user FOREIGN KEY (user_id) REFERENCES user_accounts (id),
    CONSTRAINT uq_supervisors_user UNIQUE (user_id),
    CONSTRAINT uq_supervisors_email UNIQUE (email),
    CONSTRAINT ck_supervisors_branch CHECK (branch IN ('MANILA', 'CEBU'))
);

-- -----------------------------------------------------------------------------
-- Employees.
--
-- work_category is a *profile* attribute, not a live location: a FIELD_BASED
-- employee routinely works from the office and vice versa (requirement 8).
-- -----------------------------------------------------------------------------
CREATE TABLE employees (
    id                UUID         PRIMARY KEY,
    employee_no       VARCHAR(40)  NOT NULL,
    user_id           UUID         NOT NULL,
    first_name        VARCHAR(80)  NOT NULL,
    last_name         VARCHAR(80)  NOT NULL,
    email             VARCHAR(190) NOT NULL,
    contact_number    VARCHAR(40),
    branch            VARCHAR(20)  NOT NULL,
    work_category     VARCHAR(20)  NOT NULL,
    supervisor_id     UUID,
    work_schedule_id  UUID,
    home_office_id    UUID,
    account_status    VARCHAR(30)  NOT NULL,
    hired_on          DATE,
    created_at        TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at        TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT uq_employees_employee_no UNIQUE (employee_no),
    CONSTRAINT uq_employees_user UNIQUE (user_id),
    CONSTRAINT uq_employees_email UNIQUE (email),
    CONSTRAINT fk_employees_user       FOREIGN KEY (user_id)          REFERENCES user_accounts (id),
    CONSTRAINT fk_employees_supervisor FOREIGN KEY (supervisor_id)    REFERENCES supervisors (id),
    CONSTRAINT fk_employees_schedule   FOREIGN KEY (work_schedule_id) REFERENCES work_schedules (id),
    CONSTRAINT fk_employees_office     FOREIGN KEY (home_office_id)   REFERENCES locations (id),
    CONSTRAINT ck_employees_branch   CHECK (branch IN ('MANILA', 'CEBU')),
    CONSTRAINT ck_employees_category CHECK (work_category IN ('OFFICE_BASED', 'FIELD_BASED')),
    CONSTRAINT ck_employees_status   CHECK (account_status IN ('PENDING_ACTIVATION', 'ACTIVE', 'DISABLED'))
);

CREATE INDEX ix_employees_supervisor ON employees (supervisor_id);
CREATE INDEX ix_employees_branch     ON employees (branch);

-- -----------------------------------------------------------------------------
-- Registered device credentials (WebAuthn / passkey public keys).
--
-- No raw biometric data is ever stored - only the credential id and public key
-- produced by the employee's device (requirement 13).
--
-- For the MVP an employee may hold at most one ACTIVE credential; the partial
-- unique index below enforces that in the database.
-- -----------------------------------------------------------------------------
CREATE TABLE device_credentials (
    id              UUID          PRIMARY KEY,
    employee_id     UUID          NOT NULL,
    credential_id   VARCHAR(500)  NOT NULL,
    credential_type VARCHAR(40)   NOT NULL DEFAULT 'PUBLIC_KEY',
    public_key      TEXT          NOT NULL,
    algorithm       VARCHAR(20)   NOT NULL,
    sign_count      BIGINT        NOT NULL DEFAULT 0,
    aaguid          VARCHAR(60),
    device_label    VARCHAR(120),
    status          VARCHAR(20)   NOT NULL,
    created_at      TIMESTAMPTZ   NOT NULL DEFAULT now(),
    last_used_at    TIMESTAMPTZ,
    revoked_at      TIMESTAMPTZ,
    revoked_by      UUID,
    revoked_reason  VARCHAR(300),
    CONSTRAINT uq_device_credentials_credential_id UNIQUE (credential_id),
    CONSTRAINT fk_device_credentials_employee FOREIGN KEY (employee_id) REFERENCES employees (id) ON DELETE CASCADE,
    CONSTRAINT fk_device_credentials_revoker  FOREIGN KEY (revoked_by)  REFERENCES user_accounts (id),
    CONSTRAINT ck_device_credentials_status CHECK (status IN ('ACTIVE', 'REVOKED'))
);

CREATE UNIQUE INDEX uq_device_credentials_one_active
    ON device_credentials (employee_id) WHERE status = 'ACTIVE';

-- -----------------------------------------------------------------------------
-- One-time activation invitations. Only a SHA-256 hash of the token is stored,
-- so a database leak cannot be replayed as an activation link.
-- -----------------------------------------------------------------------------
CREATE TABLE activation_tokens (
    id          UUID         PRIMARY KEY,
    user_id     UUID         NOT NULL,
    token_hash  VARCHAR(100) NOT NULL,
    expires_at  TIMESTAMPTZ  NOT NULL,
    used_at     TIMESTAMPTZ,
    invalidated BOOLEAN      NOT NULL DEFAULT FALSE,
    created_by  UUID,
    created_at  TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT uq_activation_tokens_hash UNIQUE (token_hash),
    CONSTRAINT fk_activation_tokens_user    FOREIGN KEY (user_id)    REFERENCES user_accounts (id) ON DELETE CASCADE,
    CONSTRAINT fk_activation_tokens_creator FOREIGN KEY (created_by) REFERENCES user_accounts (id)
);

CREATE INDEX ix_activation_tokens_user ON activation_tokens (user_id);

-- -----------------------------------------------------------------------------
-- Refresh tokens (hashed, rotating).
-- -----------------------------------------------------------------------------
CREATE TABLE refresh_tokens (
    id         UUID         PRIMARY KEY,
    user_id    UUID         NOT NULL,
    token_hash VARCHAR(100) NOT NULL,
    expires_at TIMESTAMPTZ  NOT NULL,
    revoked_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT uq_refresh_tokens_hash UNIQUE (token_hash),
    CONSTRAINT fk_refresh_tokens_user FOREIGN KEY (user_id) REFERENCES user_accounts (id) ON DELETE CASCADE
);

CREATE INDEX ix_refresh_tokens_user ON refresh_tokens (user_id);

-- -----------------------------------------------------------------------------
-- Short-lived WebAuthn challenges (registration and authentication).
-- -----------------------------------------------------------------------------
CREATE TABLE webauthn_challenges (
    id         UUID         PRIMARY KEY,
    user_id    UUID         NOT NULL,
    challenge  VARCHAR(200) NOT NULL,
    purpose    VARCHAR(30)  NOT NULL,
    expires_at TIMESTAMPTZ  NOT NULL,
    consumed   BOOLEAN      NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT uq_webauthn_challenges_value UNIQUE (challenge),
    CONSTRAINT fk_webauthn_challenges_user FOREIGN KEY (user_id) REFERENCES user_accounts (id) ON DELETE CASCADE,
    CONSTRAINT ck_webauthn_challenges_purpose CHECK (purpose IN ('REGISTRATION', 'AUTHENTICATION'))
);

-- -----------------------------------------------------------------------------
-- Field assignments created by supervisors and administrators.
-- -----------------------------------------------------------------------------
CREATE TABLE field_assignments (
    id               UUID         PRIMARY KEY,
    reference        VARCHAR(40)  NOT NULL,
    employee_id      UUID         NOT NULL,
    location_id      UUID         NOT NULL,
    client_name      VARCHAR(160) NOT NULL,
    assignment_date  DATE         NOT NULL,
    appointment_time TIME         NOT NULL,
    activity         VARCHAR(120) NOT NULL,
    notes            VARCHAR(1000),
    status           VARCHAR(20)  NOT NULL,
    cancel_reason    VARCHAR(400),
    created_by       UUID         NOT NULL,
    created_at       TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at       TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT uq_field_assignments_reference UNIQUE (reference),
    CONSTRAINT fk_field_assignments_employee FOREIGN KEY (employee_id) REFERENCES employees (id),
    CONSTRAINT fk_field_assignments_location FOREIGN KEY (location_id) REFERENCES locations (id),
    CONSTRAINT fk_field_assignments_creator  FOREIGN KEY (created_by)  REFERENCES user_accounts (id),
    CONSTRAINT ck_field_assignments_status CHECK (status IN ('SCHEDULED', 'IN_PROGRESS', 'COMPLETED', 'CANCELLED'))
);

CREATE INDEX ix_field_assignments_employee_date ON field_assignments (employee_id, assignment_date);
CREATE INDEX ix_field_assignments_date          ON field_assignments (assignment_date);

-- -----------------------------------------------------------------------------
-- Photo evidence. Only a storage reference lives in Postgres; the image itself
-- is kept in object storage (requirement 85).
-- -----------------------------------------------------------------------------
CREATE TABLE photo_evidence (
    id           UUID         PRIMARY KEY,
    employee_id  UUID         NOT NULL,
    storage_key  VARCHAR(400) NOT NULL,
    content_type VARCHAR(80)  NOT NULL,
    size_bytes   BIGINT       NOT NULL,
    captured_at  TIMESTAMPTZ,
    status       VARCHAR(20)  NOT NULL DEFAULT 'PENDING',
    created_at   TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT uq_photo_evidence_storage_key UNIQUE (storage_key),
    CONSTRAINT fk_photo_evidence_employee FOREIGN KEY (employee_id) REFERENCES employees (id) ON DELETE CASCADE,
    CONSTRAINT ck_photo_evidence_status CHECK (status IN ('PENDING', 'ATTACHED', 'DELETED'))
);

-- -----------------------------------------------------------------------------
-- The central work event table.
--
-- event_id is generated on the client so that re-sending a queued offline event
-- can never create a duplicate (requirement 40).
-- -----------------------------------------------------------------------------
CREATE TABLE work_events (
    id                      UUID         PRIMARY KEY,
    employee_id             UUID         NOT NULL,
    assignment_id           UUID,
    event_type              VARCHAR(30)  NOT NULL,
    event_time              TIMESTAMPTZ  NOT NULL,
    device_timestamp        TIMESTAMPTZ,
    business_date           DATE         NOT NULL,
    latitude                DOUBLE PRECISION,
    longitude               DOUBLE PRECISION,
    gps_accuracy_m          DOUBLE PRECISION,
    location_id             UUID,
    distance_to_location_m  DOUBLE PRECISION,
    within_geofence         BOOLEAN,
    destination             VARCHAR(30),
    destination_location_id UUID,
    biometric_verified      BOOLEAN      NOT NULL DEFAULT FALSE,
    credential_id           UUID,
    photo_id                UUID,
    capture_mode            VARCHAR(20)  NOT NULL DEFAULT 'ONLINE',
    sync_status             VARCHAR(20)  NOT NULL DEFAULT 'SYNCED',
    sync_timestamp          TIMESTAMPTZ,
    received_at             TIMESTAMPTZ  NOT NULL DEFAULT now(),
    disposition             VARCHAR(20)  NOT NULL DEFAULT 'ACCEPTED',
    review_status           VARCHAR(20)  NOT NULL DEFAULT 'NONE',
    reviewed_by             UUID,
    reviewed_at             TIMESTAMPTZ,
    review_notes            VARCHAR(1000),
    integrity_hash          VARCHAR(120),
    client_app_version      VARCHAR(40),
    created_at              TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT fk_work_events_employee    FOREIGN KEY (employee_id)             REFERENCES employees (id) ON DELETE CASCADE,
    CONSTRAINT fk_work_events_assignment  FOREIGN KEY (assignment_id)           REFERENCES field_assignments (id),
    CONSTRAINT fk_work_events_location    FOREIGN KEY (location_id)             REFERENCES locations (id),
    CONSTRAINT fk_work_events_destination FOREIGN KEY (destination_location_id) REFERENCES locations (id),
    CONSTRAINT fk_work_events_credential  FOREIGN KEY (credential_id)           REFERENCES device_credentials (id),
    CONSTRAINT fk_work_events_photo       FOREIGN KEY (photo_id)                REFERENCES photo_evidence (id),
    CONSTRAINT fk_work_events_reviewer    FOREIGN KEY (reviewed_by)             REFERENCES user_accounts (id),
    CONSTRAINT uq_work_events_photo UNIQUE (photo_id),
    CONSTRAINT ck_work_events_type CHECK (event_type IN (
        'TIME_IN', 'OFFICE_DEPARTURE', 'FIELD_ARRIVAL',
        'FIELD_DEPARTURE', 'OFFICE_ARRIVAL', 'TIME_OUT')),
    CONSTRAINT ck_work_events_destination CHECK (destination IS NULL OR destination IN (
        'OFFICE', 'HOME', 'ANOTHER_FIELD_LOCATION')),
    CONSTRAINT ck_work_events_capture_mode CHECK (capture_mode IN ('ONLINE', 'OFFLINE')),
    CONSTRAINT ck_work_events_sync_status  CHECK (sync_status IN ('PENDING', 'SYNCING', 'SYNCED', 'FAILED', 'FLAGGED')),
    CONSTRAINT ck_work_events_disposition  CHECK (disposition IN ('ACCEPTED', 'FLAGGED')),
    CONSTRAINT ck_work_events_review       CHECK (review_status IN ('NONE', 'REQUIRES_REVIEW', 'REVIEWED_OK', 'REVIEWED_ADJUSTED')),
    CONSTRAINT ck_work_events_lat CHECK (latitude  IS NULL OR latitude  BETWEEN -90 AND 90),
    CONSTRAINT ck_work_events_lon CHECK (longitude IS NULL OR longitude BETWEEN -180 AND 180)
);

CREATE INDEX ix_work_events_employee_date ON work_events (employee_id, business_date);
CREATE INDEX ix_work_events_time          ON work_events (event_time DESC);
CREATE INDEX ix_work_events_review        ON work_events (review_status) WHERE review_status = 'REQUIRES_REVIEW';
CREATE INDEX ix_work_events_assignment    ON work_events (assignment_id);

-- -----------------------------------------------------------------------------
-- Exceptions attached to a work event ("requires review" reasons).
-- -----------------------------------------------------------------------------
CREATE TABLE work_event_flags (
    id           UUID         PRIMARY KEY,
    work_event_id UUID        NOT NULL,
    category     VARCHAR(30)  NOT NULL,
    code         VARCHAR(60)  NOT NULL,
    severity     VARCHAR(20)  NOT NULL,
    detail       VARCHAR(500),
    created_at   TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT fk_work_event_flags_event FOREIGN KEY (work_event_id) REFERENCES work_events (id) ON DELETE CASCADE,
    CONSTRAINT uq_work_event_flags UNIQUE (work_event_id, code),
    CONSTRAINT ck_work_event_flags_category CHECK (category IN (
        'ATTENDANCE', 'LOCATION', 'AUTHENTICATION', 'ASSIGNMENT', 'OFFLINE_SYNC', 'WORKFLOW')),
    CONSTRAINT ck_work_event_flags_severity CHECK (severity IN ('INFO', 'WARNING', 'CRITICAL'))
);

CREATE INDEX ix_work_event_flags_event ON work_event_flags (work_event_id);

-- -----------------------------------------------------------------------------
-- Corrections. An accepted work event is never overwritten (requirement 60);
-- the correction is recorded here and applied on top of the original.
-- -----------------------------------------------------------------------------
CREATE TABLE event_adjustments (
    id             UUID         PRIMARY KEY,
    work_event_id  UUID         NOT NULL,
    field_name     VARCHAR(60)  NOT NULL,
    original_value VARCHAR(500),
    adjusted_value VARCHAR(500),
    reason         VARCHAR(1000) NOT NULL,
    status         VARCHAR(20)  NOT NULL,
    requested_by   UUID         NOT NULL,
    requested_at   TIMESTAMPTZ  NOT NULL DEFAULT now(),
    decided_by     UUID,
    decided_at     TIMESTAMPTZ,
    decision_note  VARCHAR(1000),
    CONSTRAINT fk_event_adjustments_event     FOREIGN KEY (work_event_id) REFERENCES work_events (id) ON DELETE CASCADE,
    CONSTRAINT fk_event_adjustments_requester FOREIGN KEY (requested_by)  REFERENCES user_accounts (id),
    CONSTRAINT fk_event_adjustments_decider   FOREIGN KEY (decided_by)    REFERENCES user_accounts (id),
    CONSTRAINT ck_event_adjustments_status CHECK (status IN ('PENDING', 'APPROVED', 'REJECTED')),
    CONSTRAINT ck_event_adjustments_field  CHECK (field_name IN ('EVENT_TIME', 'LOCATION', 'EVENT_TYPE', 'ASSIGNMENT', 'REVIEW_NOTE'))
);

CREATE INDEX ix_event_adjustments_event ON event_adjustments (work_event_id);

-- -----------------------------------------------------------------------------
-- Audit trail. Append-only; never updated or deleted by the application.
-- -----------------------------------------------------------------------------
CREATE TABLE audit_logs (
    id          UUID         PRIMARY KEY,
    occurred_at TIMESTAMPTZ  NOT NULL DEFAULT now(),
    actor_id    UUID,
    actor_label VARCHAR(160) NOT NULL,
    actor_role  VARCHAR(20)  NOT NULL,
    action      VARCHAR(80)  NOT NULL,
    target_type VARCHAR(60),
    target_id   VARCHAR(80),
    target_label VARCHAR(200),
    result      VARCHAR(20)  NOT NULL,
    detail      VARCHAR(2000),
    ip_address  VARCHAR(60),
    CONSTRAINT fk_audit_logs_actor FOREIGN KEY (actor_id) REFERENCES user_accounts (id),
    CONSTRAINT ck_audit_logs_result CHECK (result IN ('SUCCESS', 'FAILURE', 'FLAGGED', 'DENIED')),
    CONSTRAINT ck_audit_logs_actor_role CHECK (actor_role IN ('EMPLOYEE', 'SUPERVISOR', 'ADMIN', 'SYSTEM'))
);

CREATE INDEX ix_audit_logs_occurred ON audit_logs (occurred_at DESC);
CREATE INDEX ix_audit_logs_actor    ON audit_logs (actor_id);

-- -----------------------------------------------------------------------------
-- Administrator-editable system behaviour.
-- -----------------------------------------------------------------------------
CREATE TABLE system_settings (
    setting_key   VARCHAR(80)  PRIMARY KEY,
    setting_value VARCHAR(400) NOT NULL,
    description   VARCHAR(400),
    updated_by    UUID,
    updated_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT fk_system_settings_user FOREIGN KEY (updated_by) REFERENCES user_accounts (id)
);
